46	 * Base yargs parser configuration
47	 * @private
48	 */
49	const YARGS_PARSER_CONFIG = {
50	  'combine-arrays': true,
51	  'short-option-groups': false,
52	  'dot-notation': false,
53	  'strip-aliased': true
54	};
