56	/**
57	 * This is the config pulled from the `yargs` property of Mocha's
58	 * `package.json`, but it also disables camel case expansion as to
59	 * avoid outputting non-canonical keynames, as we need to do some
60	 * lookups.
61	 * @private
62	 * @ignore
63	 */
64	const configuration = Object.assign({}, YARGS_PARSER_CONFIG, {
65	  'camel-case-expansion': false
66	});
