68	/**
69	 * This is a really fancy way to:
70	 * - `array`-type options: ensure unique values and evtl. split comma-delimited lists
71	 * - `boolean`/`number`/`string`- options: use last element when given multiple times
72	 * This is passed as the `coerce` option to `yargs-parser`
73	 * @private
74	 * @ignore
75	 */
76	const globOptions = ['spec', 'ignore'];
77	const coerceOpts = Object.assign(
78	  types.array.reduce(
79	    (acc, arg) =>
80	      Object.assign(acc, {
81	        [arg]: v => Array.from(new Set(globOptions.includes(arg) ? v : list(v)))
82	      }),
83	    {}
84	  ),
85	  types.boolean
86	    .concat(types.string, types.number)
87	    .reduce(
88	      (acc, arg) =>
89	        Object.assign(acc, {[arg]: v => (Array.isArray(v) ? v.pop() : v)}),
90	      {}
91	    )
92	);
