94	/**
95	 * We do not have a case when multiple arguments are ever allowed after a flag
96	 * (e.g., `--foo bar baz quux`), so we fix the number of arguments to 1 across
97	 * the board of non-boolean options.
98	 * This is passed as the `narg` option to `yargs-parser`
99	 * @private
100	 * @ignore
101	 */
102	const nargOpts = types.array
103	  .concat(types.string, types.number)
104	  .reduce((acc, arg) => Object.assign(acc, {[arg]: 1}), {});
105	
106	/**
107	 * Throws either "UNSUPPORTED" error or "INVALID_ARG_TYPE" error for numeric positional arguments.
108	 * @param {string[]} allArgs - Stringified args passed to mocha cli
109	 * @param {number} numericArg - Numeric positional arg for which error must be thrown
110	 * @param {Object} parsedResult - Result from `yargs-parser`
111	 * @private
112	 * @ignore
113	 */
114	const createErrorForNumericPositionalArg = (
115	  numericArg,
116	  allArgs,
117	  parsedResult
118	) => {
119	  // A flag for `numericArg` exists if:
120	  // 1. A mocha flag immediately preceeded the numericArg in `allArgs` array and
121	  // 2. `numericArg` value could not be assigned to this flag by `yargs-parser` because of incompatible datatype.
122	  const flag = allArgs.find((arg, index) => {
123	    const normalizedArg = arg.replace(/^--?/, '');
124	    return (
125	      isMochaFlag(arg) &&
126	      allArgs[index + 1] === String(numericArg) &&
127	      parsedResult[normalizedArg] !== String(numericArg)
128	    );
129	  });
130	
131	  if (flag) {
132	    throw createInvalidArgumentTypeError(
133	      `Mocha flag '${flag}' given invalid option: '${numericArg}'`,
134	      numericArg,
135	      expectedTypeForFlag(flag)
136	    );
137	  } else {
138	    throw createUnsupportedError(
139	      `Option ${numericArg} is unsupported by the mocha cli`
140	    );
141	  }
142	};
