144	/**
145	 * Wrapper around `yargs-parser` which applies our settings
146	 * @param {string|string[]} args - Arguments to parse
147	 * @param {Object} defaultValues - Default values of mocharc.json
148	 * @param  {...Object} configObjects - `configObjects` for yargs-parser
149	 * @private
150	 * @ignore
151	 */
152	const parse = (args = [], defaultValues = {}, ...configObjects) => {
153	  // save node-specific args for special handling.
154	  // 1. when these args have a "=" they should be considered to have values
155	  // 2. if they don't, they are just boolean flags
156	  // 3. to avoid explicitly defining the set of them, we tell yargs-parser they
157	  //    are ALL boolean flags.
158	  // 4. we can then reapply the values after yargs-parser is done.
159	  const allArgs = Array.isArray(args) ? args : args.split(' ');
160	  const nodeArgs = allArgs.reduce((acc, arg) => {
161	    const pair = arg.split('=');
162	    let flag = pair[0];
163	    if (isNodeFlag(flag, false)) {
164	      flag = flag.replace(/^--?/, '');
165	      return acc.concat([[flag, arg.includes('=') ? pair[1] : true]]);
166	    }
167	    return acc;
168	  }, []);
169	
170	  const result = yargsParser.detailed(args, {
171	    configuration,
172	    configObjects,
173	    default: defaultValues,
174	    coerce: coerceOpts,
175	    narg: nargOpts,
176	    alias: aliases,
177	    string: types.string,
178	    array: types.array,
179	    number: types.number,
180	    boolean: types.boolean.concat(nodeArgs.map(pair => pair[0]))
181	  });
182	  if (result.error) {
183	    console.error(ansi.red(`Error: ${result.error.message}`));
184	    process.exit(1);
185	  }
186	
187	  const numericPositionalArg = result.argv._.find(arg => isNumeric(arg));
188	  if (numericPositionalArg) {
189	    createErrorForNumericPositionalArg(
190	      numericPositionalArg,
191	      allArgs,
192	      result.argv
193	    );
194	  }
195	
196	  // reapply "=" arg values from above
197	  nodeArgs.forEach(([key, value]) => {
198	    result.argv[key] = value;
199	  });
200	
201	  return result.argv;
202	};
